export const ZANZIBAR_REGIONS = new Set<string>([
  "Mjini Magharibi",
  "Pemba North",
  "Pemba South",
  "Zanzibar North",
  "Zanzibar South & Central"
]);

export const regionOptions = Object.keys(TANZANIA_LOCATIONS).map((name) => ({
    value: name,
    label: name,
    group: ZANZIBAR_REGIONS.has(name) ? 'Zanzibar' : 'Tanzania Bara',
}));

export const districtOptions = (region: string) =>
    Object.keys(TANZANIA_LOCATIONS[region] ?? {}).map((name) => ({ value: name, label: name }));

export const streetOptions = (region: string, district: string) =>
    (TANZANIA_LOCATIONS[region]?.[district] ?? []).map((name) => ({ value: name, label: name }));
